insert into content.content_block (place_id,section,slot,ord,body,fact_refs,status,author,field) values
('area:paradiski','meta','line',0,'Paradiski | Linked ski areas | Snow Catchers','{}'::text[],'review','loader','title'),
('area:paradiski','meta','line',1,'How La Plagne and Les Arcs fit together across the Vanoise Express, which base reaches which side, how the snow changes with height, when the Paradiski pass pays, and what the area is like for boarders, families, food and evenings.','{}'::text[],'review','loader','description'),
('area:paradiski','meta','line',2,'France','{}'::text[],'review','loader','crumbs.0.label'),
('area:paradiski','meta','line',3,'Linked ski areas','{}'::text[],'review','loader','crumbs.1.label'),
('area:paradiski','meta','line',4,'Northern Alps','{}'::text[],'review','loader','crumbs.2.label'),
('area:paradiski','hero','lead',0,'La Plagne and Les Arcs, two of the big resorts of the Tarentaise, sit on facing slopes with a deep valley between them, and since {{f:F000246}} the Vanoise Express cable car has carried skiers across it. The operator counts {{f:F000219}} of piste and {{f:F000220}} runs, from the woods above Villaroger to the Aiguille Rouge at {{f:F000221}}. A single day can begin among the high apartment blocks of Plagne Centre and end on the forest runs above Peisey.',array['F000219','F000220','F000221','F000246']::text[],'review','loader','hero.lead'),
('area:paradiski','stats','line',0,'{{f:F000071}}',array['F000071']::text[],'review','loader','stats.0.v'),
('area:paradiski','stats','line',1,'of linked piste on skiresort.com, the same as the operator''s count','{}'::text[],'review','loader','stats.0.t'),
('area:paradiski','stats','line',2,'{{f:F000247}}',array['F000247']::text[],'review','loader','stats.1.v'),
('area:paradiski','stats','line',3,'the span of the Vanoise Express, {{f:F000248}} above the valley floor and the only lift between the two resorts',array['F000248']::text[],'review','loader','stats.1.t'),
('area:paradiski','stats','line',4,'{{f:F000073|n}} to {{f:F000074}}',array['F000073','F000074']::text[],'review','loader','stats.2.v'),
('area:paradiski','stats','line',5,'from the lowest lift at Villaroger to the Aiguille Rouge, on skiresort.com','{}'::text[],'review','loader','stats.2.t'),
('area:paradiski','stats','line',6,'{{f:F000066}}',array['F000066']::text[],'review','loader','stats.3.v'),
('area:paradiski','stats','line',7,'for six days, adult, high season 2026/27; the single resort passes cost {{diff:F000066,F000258}} to {{diff:F000066,F000265}} less',array['F000066','F000258','F000265']::text[],'review','loader','stats.3.t'),
('area:paradiski','network','heading',0,'Two resorts and one cable car','{}'::text[],'review','loader','network.h2'),
('area:paradiski','network','para',0,'Paradiski is two ski areas joined at a single point. La Plagne spreads over a high bowl of purpose built villages above Aime, with Montalbert, Champagny-en-Vanoise and Montchavin-Les Coches on its lower flanks. Les Arcs climbs from Bourg-Saint-Maurice through Arc 1600, Arc 1800, Arc 1950 and Arc 2000, with Peisey-Vallandry and Villaroger at its edges. The Vanoise Express joins Montchavin-Les Coches to Peisey-Vallandry, and in the map data it is the only lift between the two resorts.','{}'::text[],'review','loader','network.paras.0'),
('area:paradiski','network','para',1,'Everything between the two halves rests on that crossing. Closing the Vanoise Express cuts {{f:F000356}} pairs of sectors off from each other, every journey from one resort to the other. Two more lifts matter nearly as much. Without the Peisey chair, skiers from La Plagne reach Peisey-Vallandry but cannot go on into the rest of Les Arcs, and without the Montalbert gondola none of the other {{f:F000358|w}} sectors can be reached from Montalbert by lift.',array['F000356','F000358']::text[],'review','loader','network.paras.1'),
('area:paradiski','network','para',2,'La Plagne also leans on a few lifts within its own bowl. Closing the Bijolin chair on the Montchavin-Les Coches side adds {{f:F000359}} lift rides in total across the journeys between sectors, and closing the Colosses chair at Plagne Bellecôte adds {{f:F000360}}. The villages of Les Arcs are linked to each other more than one way, so a single closure there costs time rather than access.',array['F000359','F000360']::text[],'review','loader','network.paras.2'),
('area:paradiski','network','line',0,'{{m:all.plagne-centre.arc-2000}} lift rides','{}'::text[],'review','loader','network.figs.0.v'),
('area:paradiski','network','line',1,'from the first lifts of Plagne Centre to Arc 2000, and {{m:all.arc-2000.plagne-centre|w}} back','{}'::text[],'review','loader','network.figs.0.t'),
('area:paradiski','network','line',2,'One lift','{}'::text[],'review','loader','network.figs.1.v'),
('area:paradiski','network','line',3,'joins the two resorts: the Vanoise Express, built for more than {{f:F000249}} people a cabin',array['F000249']::text[],'review','loader','network.figs.1.t'),
('area:paradiski','network','line',4,'{{m:all.montalbert.villaroger}} lift rides','{}'::text[],'review','loader','network.figs.2.v'),
('area:paradiski','network','line',5,'from Montalbert to Villaroger, the longest crossing of the area, and {{m:all.villaroger.montalbert|w}} back','{}'::text[],'review','loader','network.figs.2.t'),
('area:paradiski','network','line',6,'{{f:F000356}} pairs',array['F000356']::text[],'review','loader','network.figs.3.v'),
('area:paradiski','network','line',7,'of sectors lose their link if the Vanoise Express stops','{}'::text[],'review','loader','network.figs.3.t'),
('area:paradiski','network','line',8,'{{f:F000239}}',array['F000239']::text[],'review','loader','network.figs.4.v'),
('area:paradiski','network','line',9,'La Plagne opens with two drag lifts, built to keep the valley villages alive as farming and mining decline','{}'::text[],'review','loader','network.figs.4.t'),
('area:paradiski','network','line',10,'{{f:F000241}}',array['F000241']::text[],'review','loader','network.figs.5.v'),
('area:paradiski','network','line',11,'Arc 1600 opens, the first of the Arc villages, designed with Charlotte Perriand','{}'::text[],'review','loader','network.figs.5.t'),
('area:paradiski','network','heading',1,'Explore the network','{}'::text[],'review','loader','network.mapTitle'),
('area:paradiski','network','caption',0,'Choose a starting point to see how many lift rides it takes to reach each other area, then limit the runs to see what stays within reach.','{}'::text[],'review','loader','network.mapHelp'),
('area:paradiski','network','caption',1,'Schematic, not to scale, with sectors moved apart for legibility. Built from OpenStreetMap lift and piste data (© OpenStreetMap contributors, snapshot 24 October 2026) with heights from the Copernicus 90 m elevation model. An orange link carries routes that no other link replaces when a single lift on it closes. Lift rides are the fewest needed between the lift bases of two areas. The model is being checked against the official 2026/27 piste map.','{}'::text[],'review','loader','network.caption'),
('area:paradiski','network','line',12,'Bellecôte','{}'::text[],'review','loader','sectors.2.short'),
('area:paradiski','network','line',13,'Champagny','{}'::text[],'review','loader','sectors.3.short'),
('area:paradiski','network','line',14,'Montchavin','{}'::text[],'review','loader','sectors.4.short'),
('area:paradiski','network','line',15,'Peisey','{}'::text[],'review','loader','sectors.5.short'),
('area:paradiski','network','line',16,'Aiguille Rouge','{}'::text[],'review','loader','mapNotes.0.text'),
('area:paradiski','network','line',17,'Roche de Mio','{}'::text[],'review','loader','mapNotes.1.text'),
('area:paradiski','routes','heading',0,'Five sample days','{}'::text[],'review','loader','routes.h3'),
('area:paradiski','routes','line',0,'Each trip is counted in lift rides out and back, from the first lift base in each area, with the easiest grade of run that makes it in the map data. The counts start lower than the base table further down, which starts in the village. Time on the pistes, in queues and on foot is not included.','{}'::text[],'review','loader','routes.intro'),
('area:paradiski','routes','line',1,'Plagne Centre','{}'::text[],'review','loader','routes.rows.0.from'),
('area:paradiski','routes','line',2,'Arc 2000','{}'::text[],'review','loader','routes.rows.0.to'),
('area:paradiski','routes','line',3,'Green and blue','{}'::text[],'review','loader','routes.rows.0.grade'),
('area:paradiski','routes','note',0,'Out over the Arpette and the Vanoise Express, home by the Bijolin and Colosses chairs.','{}'::text[],'review','loader','routes.rows.0.note'),
('area:paradiski','routes','line',4,'Plagne Bellecôte','{}'::text[],'review','loader','routes.rows.1.from'),
